import{_ as a}from"./chunks/settings-cal.pc.en.X2_AiM35.js";import{_ as e,o,c as n,a5 as i}from"./chunks/framework.D47SInms.js";const g=JSON.parse('{"title":"4. ZMP Calibration","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/add-on/zmp-calibration.md","filePath":"guides/add-on/zmp-calibration.md","lastUpdated":1791600043000}'),r={name:"guides/add-on/zmp-calibration.md"};function s(l,t,d,h,c,u){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="_4-zmp-calibration" tabindex="-1">4. ZMP Calibration <a class="header-anchor" href="#_4-zmp-calibration" aria-label="Permalink to &quot;4. ZMP Calibration&quot;">​</a></h1><p><strong>Goal:</strong> Recalibrate the Zero Moment Point so the robot stays balanced under the weight the add-on module has changed.</p><p><strong>Prerequisites:</strong> Step 3, <a href="/RBQ/nightly/guides/add-on/payload-setting.html">Payload Setting</a>, must be complete — the mass and center of mass have to be registered on the robot.</p><h2 id="what-zmp-calibration-does" tabindex="-1">What ZMP calibration does <a class="header-anchor" href="#what-zmp-calibration-does" aria-label="Permalink to &quot;What ZMP calibration does&quot;">​</a></h2><p>ZMP (Zero Moment Point) calibration aligns the center of the ground reaction force while the robot stands, so it stays balanced as it walks. A changed payload moves the center of mass, which is why this step is needed.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Put the robot on <strong>flat, firm ground</strong>.</li><li>Clear the area so <strong>nothing and nobody touches the robot</strong>, and leave <strong>room for one step</strong>.</li><li>The app must be connected and <strong>the robot must be standing</strong> (STAND). It cannot start while sitting.</li></ul><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li>Open <strong>Maintenance → Calibration</strong> in the app.</li></ol><figure style="text-align:center;"><img src="'+a+'" alt="Maintenance → Calibration" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 1 — Maintenance → Calibration</figcaption></figure><ol start="2"><li>Under <strong>ZMP Calibration</strong>, press <code>Auto-calibrate ZMP offset</code>. If the robot cannot run it, the button is locked and the reason appears right there.</li><li>Confirm in the dialog.</li><li>The robot <strong>takes one step to square up its legs</strong>, then calibrates — <strong>up to 60 seconds</strong>.</li><li>When it is done the robot <strong>saves the value itself and returns to STAND.</strong></li><li>Switch Stance → Walk and confirm the robot walks normally with the module fitted.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Do not put anything on the robot or push it during calibration. A failure leaves the previous calibration in place; what to do for each reason is listed in <a href="/RBQ/nightly/manual/troubleshooting/calibration-tuning">Calibration and tuning</a>.</p></div></div><h2 id="done" tabindex="-1">Done <a class="header-anchor" href="#done" aria-label="Permalink to &quot;Done&quot;">​</a></h2><p>The add-on module is fitted, the payload is registered and the ZMP is calibrated. You can send motion commands as usual — see <strong><a href="/RBQ/nightly/manual/gui/motion-commands.html">Motion commands</a></strong> for driving the robot.</p>',14)])])}const m=e(r,[["render",s]]);export{g as __pageData,m as default};
